const oAuthRefreshTokenRecordsByGrant = `-- name: OAuthRefreshTokenRecordsByGrant :many
SELECT id, data_json FROM credbound.oauth_refresh_tokens WHERE grant_id = $1 AND revoked_at IS NULL
`

type OAuthRefreshTokenRecordsByGrantRow struct {
	ID       string          `json:"id"`
	DataJson json.RawMessage `json:"data_json"`
}

func (q *Queries) OAuthRefreshTokenRecordsByGrant(ctx context.Context, grantID string) ([]OAuthRefreshTokenRecordsByGrantRow, error) {
	rows, err := q.db.QueryContext(ctx, oAuthRefreshTokenRecordsByGrant, grantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OAuthRefreshTokenRecordsByGrantRow
	for rows.Next() {
		var i OAuthRefreshTokenRecordsByGrantRow
		if err := rows.Scan(&i.ID, &i.DataJson); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

